// The report content model, shared by the Word and PDF renderers.
import { tablesAfter, titledTables } from './md.mjs'

const H1 = (text) => ({ t: 'h1', text })
const H2 = (text) => ({ t: 'h2', text })
const H3 = (text) => ({ t: 'h3', text })
const P = (text) => ({ t: 'p', text })
const B = (...items) => ({ t: 'bullets', items })
const N = (...items) => ({ t: 'numbers', items })
const T = (caption, head, rows, widths, opts = {}) => ({ t: 'table', caption, head, rows, widths, ...opts })
const F = (src, caption, opts = {}) => ({ t: 'fig', src, caption, ...opts })
const C = (title, text) => ({ t: 'callout', title, text })
const BR = { t: 'pagebreak' }
const pick = (tbl, cols) => ({ head: cols.map((c) => tbl.head[c]), rows: tbl.rows.map((r) => cols.map((c) => r[c] ?? '')) })

